import 'package:flutter/material.dart';
import 'package:geolocator/geolocator.dart';
import 'package:mobile_scanner/mobile_scanner.dart';
import 'package:intl/intl.dart';
import '../models/intervention.dart';
import '../services/database_service.dart';
import '../services/scanner_service.dart';

class InterventionScreen extends StatefulWidget{final String enterprise;const InterventionScreen({super.key,required this.enterprise});@override State<InterventionScreen> createState()=>_InterventionScreenState();}
class _InterventionScreenState extends State<InterventionScreen>{final pdl=TextEditingController(),d1=TextEditingController(),d2=TextEditingController();Position? position;bool busy=false;void msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
 Future<void> scan(TextEditingController target,{bool bill=false})async{final value=await Navigator.push<String>(context,MaterialPageRoute(builder:(_)=>_Scanner(bill:bill)));if(value==null)return;final parsed=bill?ScannerService.pdlFrom(value):value; if(parsed==null){msg('Code PDL non reconnu ou ambigu. Saisissez-le manuellement.');return;}target.text=parsed;}
 Future<void> gps()async{try{if(!await Geolocator.isLocationServiceEnabled())throw Exception('Activez la localisation GPS.');var perm=await Geolocator.checkPermission();if(perm==LocationPermission.denied)perm=await Geolocator.requestPermission();if(perm==LocationPermission.denied||perm==LocationPermission.deniedForever)throw Exception('Autorisation GPS refusée.');position=await Geolocator.getCurrentPosition();setState((){});}catch(e){msg('$e');}}
 Future<void> save()async{if(pdl.text.trim().isEmpty||d1.text.trim().isEmpty||d2.text.trim().isEmpty){msg('Remplissez le PDL et les deux détecteurs.');return;}if(d1.text.trim()==d2.text.trim()){msg('Les deux détecteurs doivent être différents.');return;}if(position==null){await gps();if(position==null)return;}setState(()=>busy=true);try{await DatabaseService.instance.add(Intervention(pdl:pdl.text.trim(),detector1:d1.text.trim(),detector2:d2.text.trim(),latitude:position!.latitude,longitude:position!.longitude,enterprise:widget.enterprise,createdAt:DateFormat("yyyy-MM-dd'T'HH:mm:ss").format(DateTime.now())));if(mounted)Navigator.pop(context,true);}catch(e){msg('Enregistrement refusé : PDL ou numéro de détecteur déjà utilisé. $e');}finally{if(mounted)setState(()=>busy=false);}}
 Widget field(String label,TextEditingController ctl,{bool bill=false})=>Padding(padding:const EdgeInsets.only(bottom:14),child:TextField(controller:ctl,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder(),suffixIcon:IconButton(icon:const Icon(Icons.qr_code_scanner),onPressed:()=>scan(ctl,bill:bill)))));
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Nouvelle intervention')),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Identification sur facture Sonelgaz et détecteurs',style:TextStyle(fontWeight:FontWeight.w600)),const SizedBox(height:16),field('Référence client / PDL',pdl,bill:true),field('Code détecteur CO n°1',d1),field('Code détecteur CO n°2',d2),Card(child:ListTile(leading:Icon(position==null?Icons.gps_fixed:Icons.location_on,color:position==null?null:Colors.green),title:Text(position==null?'Position GPS non capturée':'Position GPS capturée'),subtitle:position==null?const Text('Requise pour enregistrer'):Text('${position!.latitude}, ${position!.longitude}'),trailing:TextButton(onPressed:gps,child:const Text('CAPTURER')))),const SizedBox(height:18),FilledButton.icon(onPressed:busy?null:save,icon:const Icon(Icons.save),label:Text(busy?'Enregistrement…':'Enregistrer l’intervention'))]));}
}
class _Scanner extends StatefulWidget{final bool bill;const _Scanner({required this.bill});@override State<_Scanner> createState()=>_ScannerState();}
class _ScannerState extends State<_Scanner>{bool done=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.bill?'Scanner facture / PDL':'Scanner détecteur')),body:MobileScanner(onDetect:(capture){if(done)return;final v=ScannerService.first(capture);if(v!=null){done=true;Navigator.pop(c,v);}},errorBuilder:(c,e,child)=>Center(child:Text('Caméra indisponible : $e'))));}
